local({
  k <- cbind(as.numeric(th6b), as.numeric(th6c))
  k[!(k %in% 1:3)] <- NA
  rowMeans(4 - k)
})

local({
  s2001 <- "CHIS adolescent interview (self); monitoring (self): how much parents really know, 2 of 6 items (what you do with your free time, where you are most afternoons), 1-3 item scoring (range 1-3), mean, reversed (4 - x) so know a lot = 3, complete-case, don't know and refused NA; study items, no published scoring"
  s2005 <- "CHIS adolescent interview (self); monitoring (self): how much parents really know, 2 of 3 items (what you do with your free time, where you are most afternoons), 1-3 item scoring (range 1-3), mean, reversed (4 - x) so know a lot = 3, complete-case, CHIS-imputed don't know and refused answers used as released; study items, no published scoring"
  case_when(
    cohort == "teen" & .wave == "2001" ~ s2001,
    cohort == "teen" & .wave == "2005" ~ s2005,
    .default = NA_character_
  )
})

local({
  flags <- cbind(tg11_x, tg12_x, tg13_x, tg14_x, tg15_x, tg16_x)
  imputed <- rowSums(!is.na(flags) & flags != -10) > 0
  if_else(as.numeric(distress) >= 0 & !imputed, as.numeric(distress), NA_real_)
})

local({
  flags <- cbind(td6_x, td7_x, td8_x, td9_x, td10_x, td11_x, td12_x, td13_x)
  imputed <- rowSums(!is.na(flags) & flags != -10) > 0
  if_else(as.numeric(cesd8) >= 0 & !imputed, as.numeric(cesd8), NA_real_)
})

local({
  inch <- coalesce(as.numeric(haven::zap_labels(hghti)), as.numeric(haven::zap_labels(hghti_p)))
  lb <- coalesce(as.numeric(haven::zap_labels(wghtp)), as.numeric(haven::zap_labels(wghtp_p)))
  ok <- inch > 0 & lb > 0
  case_when(!(ok %in% TRUE) ~ NA_character_, cohort == "child" ~ "Parent-reported", .default = "Self-reported")
})

local({
  m <- as.numeric(haven::zap_labels(th27))
  age <- as.numeric(haven::zap_labels(srage_p))
  case_when(!is.na(th27_x) & th27_x != -10 ~ NA_real_, m == 0 ~ 0, m > 0 & m <= age ~ 1, m > age ~ 0)
})
